1	import type { Db } from "@paperclipai/db";
2	import type { StorageService } from "../storage/types.js";
3	
4	export interface ActorMembership {
5	  companyId: string;
6	  membershipRole: string;
7	  status: string;
8	}
9	
10	export type ActorSource =
11	  | "local_implicit"
12	  | "session"
13	  | "board_key"
14	  | "agent_jwt"
15	  | "agent_key"
16	  | "none";
17	
18	export interface BoardActor {
19	  type: "board";
20	  source: ActorSource;
21	  userId: string;
22	  userName: string | null;
23	  userEmail: string | null;
24	  isInstanceAdmin: boolean;
25	  companyIds?: string[];
26	  memberships?: ActorMembership[];
27	  keyId?: string;
28	  runId?: string;
29	}
30	
31	export interface AgentActor {
32	  type: "agent";
33	  source: ActorSource;
34	  agentId: string;
35	  companyId: string;
36	  keyId?: string;
37	  runId?: string;
38	}
39	
40	/** Full actor — mirrors the shape set by actorMiddleware. null when unauthenticated ("none"). */
41	export type ActorContext = BoardActor | AgentActor;
42	
43	/** Minimal normalized request passed to every handler. */
44	export interface RequestCtx {
45	  method: string;
46	  url: URL;
47	  headers: Headers;
48	  json<T = unknown>(): Promise<T>;
49	  text(): Promise<string>;
50	  /** Path param: e.g. ctx.param("companyId") */
51	  param(name: string): string | undefined;
52	  /** Query param */
53	  query(name: string): string | undefined;
54	  actor: ActorContext | null;
55	  db: Db;
56	  storage: StorageService;
57	}
58	
59	export type Handler = (ctx: RequestCtx) => Promise<Response>;
60	
61	export interface RouteDefinition {
62	  method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
63	  /** Express-style path, e.g. /api/companies/:companyId */
64	  path: string;
65	  handler: Handler;
66	}
